const DevelopmentUI=(()=>{
function researchIcon(key){const settlement=DevelopmentArt.settlementResearch[key];return settlement?`<span class="research-icon research-settlement" data-research-art="${key}">${SettlementUI.emblem(settlement)}</span>`:DevelopmentArt.icon(key);}
function researchEntry(key,detail=''){return `<div class="research-entry">${researchIcon(key)}<div><strong>${esc(R.development.techs[key].name)}</strong>${detail}</div></div>`;}
function amounts(stock){return R.goods.filter(g=>stock[g]).map(g=>stock[g]+' '+g).join(' · ')||'Nothing';}
function exchangeList(host,kind){const D=R.development,list=state.exchangeOffers.filter(o=>(o.from===active||o.to===active)&&(kind==='trade'?o.kind==='trade':o.kind!=='trade'));for(const o of list){const row=document.createElement('article');row.className='event';const detail=o.kind==='trade'?`${country(o.from)} gives ${amounts(o.data.give)}; ${country(o.to)} gives ${amounts(o.data.want)}.`:D.techs[o.data.tech].name;row.innerHTML=`<p><strong>${esc(country(o.from))} → ${esc(country(o.to))}</strong> · ${esc(o.kind)} · ${esc(o.status)}</p><p>${esc(detail)}</p>${o.status==='pending'?`${o.to===active?'<button class="accept-exchange">Accept offer</button> ':''}<button class="cancel-exchange">${o.from===active?'Cancel offer':'Decline offer'}</button>`:''}`;row.querySelector('.accept-exchange')?.addEventListener('click',()=>change(s=>D.accept(s,active,o.id),'Offer accepted.'));row.querySelector('.cancel-exchange')?.addEventListener('click',()=>change(s=>D.cancel(s,active,o.id),'Offer closed; reserved trade resources returned.'));host.append(row);}}
function relationControls(host,selectId,buttons){const D=R.development,blocked=state.countries.filter(c=>c.id!==active&&D.disruption(state,active,c.id)),note=document.createElement('p');note.className='diplomatic-warning';note.setAttribute('role','status');host.append(note);const select=$(selectId),update=()=>{const other=select?Number(select.value):-1,x=D.disruption(state,active,other);note.textContent=x?`Relations with ${country(other)} are disrupted. No trade, knowledge sharing or joint research through round ${x.lastAttack+1}; a full quiet round restores exchange in round ${x.lastAttack+2}. Independent research continues.`:blocked.length?'Disrupted relations: '+blocked.map(c=>country(c.id)+' (through round '+(D.disruption(state,active,c.id).lastAttack+1)+')').join('; ')+'. Other partners remain available.':'Attacks cancel partnerships and pending offers, and block exchanges until one full round without another attack. Completed trades and discoveries remain.';for(const id of buttons)if($(id))$(id).disabled=state.phase!=='orders'||!!x;};select?.addEventListener('change',update);update();}
function trades(panel){const D=R.development,c=state.countries[active],host=document.createElement('section');host.className='development-block';host.innerHTML=`<h3>Economy · trade resources</h3><p>Your specialty: <strong>${c.specialty}</strong> — +25% ${D.specialties[c.specialty].good} production and cheaper ${D.specialties[c.specialty].branch} research. Other countries have different specialties and geography.</p><details><summary>Compare countries and their last production</summary>${state.countries.map(k=>`<p>${esc(k.name)} · ${k.specialty} · ${amounts(state.history[0]?.income.find(i=>i.country===k.id)||{})}</p>`).join('')}</details>${state.phase==='orders'?`<p>Trade unreserved Treasury resources. Your offer is reserved immediately. The other economist must accept and pay the requested resources. Unaccepted offers return at round-end. Prices are negotiated by students.</p><label>Trade with <select id="tradePartner">${options(state.countries.filter(k=>k.id!==active).map(k=>[k.id,k.name+' · '+k.specialty]),'')}</select></label><div class="allocation-list">${['give','want'].map(side=>`<fieldset><legend>${side==='give'?'We give':'We request'}</legend>${R.goods.map(g=>`<label>${ResourceUI.label(g)}<input type="number" min="0" step="1" value="0" class="trade-input" data-side="${side}" data-resource="${g}"></label>`).join('')}</fieldset>`).join('')}</div><button id="offerTrade">Send resource offer</button>`:'<p>New trades and acceptance open during planning.</p>'}`;panel.append(host);if($('offerTrade'))$('offerTrade').onclick=()=>{const data={give:{},want:{}};host.querySelectorAll('.trade-input').forEach(i=>data[i.dataset.side][i.dataset.resource]=Number(i.value));change(s=>D.offer(s,active,Number($('tradePartner').value),'trade',data),'Trade offered. Your resources are reserved until acceptance, cancellation or round-end.');};relationControls(host,'tradePartner',['offerTrade']);exchangeList(host,'trade');host.querySelectorAll('button').forEach(b=>{if(state.phase!=='orders')b.disabled=true;});}
function graph(host){const box=document.createElement('section');box.className='development-block';box.innerHTML='<h3>Resources gained each round</h3><p>Actual production entering Treasury, before spending or trade. Discoveries and captured land can change these lines.</p><label>Resource <select id="researchMetric"><option value="all">All resources</option>'+R.goods.map(g=>`<option>${g}</option>`).join('')+'</select></label><div id="productionGraph"></div>';host.append(box);const draw=()=>{const logs=state.history.slice(0,12).reverse(),selected=$('researchMetric').value,goods=selected==='all'?R.goods:[selected],colors={money:'#966114',food:'#24733e',wood:'#735232',metal:'#4964b2'},max=Math.max(1,...logs.flatMap(h=>goods.map(g=>h.income.find(i=>i.country===active)?.[g]||0)));if(!logs.length){$('productionGraph').textContent='Finish a round to begin your production history. No estimated data is plotted.';return;}const x=i=>55+i*600/Math.max(1,logs.length-1),y=n=>220-n/max*170;$('productionGraph').innerHTML=`<svg viewBox="0 0 700 270" role="img" aria-label="Actual production by turn"><path d="M55 40V220H670" fill="none" stroke="#526659"/><text x="5" y="50">${max}</text><text x="20" y="225">0</text>${logs.map((h,i)=>`<text x="${x(i)}" y="245" text-anchor="middle">${h.turn}</text>`).join('')}<text x="320" y="265">Round</text>${goods.map(g=>`<polyline points="${logs.map((h,i)=>`${x(i)},${y(h.income.find(k=>k.country===active)?.[g]||0)}`).join(' ')}" fill="none" stroke="${colors[g]}" stroke-width="3"/>${logs.map((h,i)=>{const n=h.income.find(k=>k.country===active)?.[g]||0;return `<circle cx="${x(i)}" cy="${y(n)}" r="4" fill="${colors[g]}"><title>${g}: ${n}, round ${h.turn}</title></circle>`;}).join('')}`).join('')}</svg><p>${goods.map(g=>`<span style="color:${colors[g]}">● ${g}</span>`).join(' · ')}</p><p>Latest actual gains: ${amounts(logs.at(-1).income.find(i=>i.country===active)||{})}</p>${logs.slice(-3).flatMap(h=>h.events.filter(e=>e.includes(country(active))&&/discovered|captured|trade completed/.test(e)).map(e=>`<p>Round ${h.turn}: ${esc(e)}</p>`)).join('')}`;};$('researchMetric').onchange=draw;draw();}
function researchCategories(c,locked){
 const D=R.development,branches=[...new Set(Object.values(D.techs).map(t=>t.branch))];
 return branches.map((branch,index)=>`<section class="research-category" aria-labelledby="research-branch-${index}"><h4 id="research-branch-${index}">${esc(branch)}</h4><div class="research-track" tabindex="0" role="region" aria-label="${esc(branch)} research; scroll horizontally">${Object.entries(D.techs).filter(([,t])=>t.branch===branch).map(([key,t])=>{
  const known=D.has(c,key),missing=t.prereq.filter(k=>!D.has(c,k)),selected=c.project===key;
  const status=known?'Completed':missing.length?'Locked':selected?(c.funding?'Funded this round':'Current project'):'Available';
  return `<article class="research-step ${known?'is-complete':missing.length?'is-locked':selected?'is-current':'is-available'}" data-technology="${key}">${researchIcon(key)}<h5>${esc(t.name)}</h5><span class="research-state">${missing.length?'🔒 ':known?'✓ ':''}${status}</span><p class="research-requirements">${missing.length?'Requires: '+missing.map(k=>esc(D.techs[k].name)).join('; '):t.prereq.length?'Prerequisites complete':t.rounds?'No prerequisites':'Starting discovery'}</p>${t.rounds?`<p>${known?t.rounds:c.researchProgress[key]||0}/${t.rounds} progress</p>${known?'':`<p class="research-price">${amounts(D.researchCost(c,key))}<br>per funded round</p>`}`:''}<button type="button" data-research-pick="${key}" aria-label="${esc((missing.length?'Locked: ':known?'Completed: ':'Choose project: ')+t.name)}" ${locked||c.funding||known||missing.length||selected?'disabled':''}>${known?'Completed':missing.length?'Locked':selected?'Selected':'Choose project'}</button></article>`;
 }).join('')}</div></section>`).join('');
}
function research(){const D=R.development,c=state.countries[active],host=$('decisions'),locked=state.phase!=='orders';$('decisionTitle').textContent='R&D · discoveries and city actions';host.innerHTML=`<p>Pending after this round: ${stockText(c.allocations.research)}. Your specialty is ${c.specialty}: 25% lower installment costs in ${D.specialties[c.specialty].branch}.</p><p>City interiors are shown only in the R&D view. This teacher-hosted device has role views, not secure student logins.</p>`;
 const section=document.createElement('section');section.className='development-block research-projects';
 section.innerHTML=`<h3>Research by category</h3><p>Choose an available discovery below, then fund one installment each planning round. Finish every required discovery before the next tier unlocks. Progress resolves after the full round.</p><div class="research-current"><p>Current project:</p>${c.project?researchEntry(c.project,`<p>${c.researchProgress[c.project]||0}/${D.techs[c.project].rounds} progress · ${amounts(D.researchCost(c))} per funded round.</p>`):'<p>Choose a project from a category below.</p>'}</div><button id="fundTechnology" ${locked||!c.project||c.funding||!D.canLearn(c,c.project)||!R.goods.every(g=>c.accounts.research[g]>=D.researchCost(c)[g])?'disabled':''}>${c.funding?'Funded for this round':'Fund one round of research'}</button><p>One national project at a time. Changing an unfunded project keeps its progress.${locked?' Research opens during planning.':c.funding?' Your project is locked until this round resolves.':c.project&&!R.goods.every(g=>c.accounts.research[g]>=D.researchCost(c)[g])?' More Research resources are needed for the next installment.':''}</p><p class="research-scroll-hint">Scroll sideways within a category to see every discovery. Locked cards list all missing prerequisites.</p>${researchCategories(c,locked)}`;
 host.append(section);
 section.querySelectorAll('[data-research-pick]').forEach(button=>button.onclick=()=>{if(button.disabled)return;change(s=>D.selectResearch(s,active,button.dataset.researchPick),'Research project selected. Fund it when resources are ready.');});
 $('fundTechnology').onclick=()=>change(s=>D.fundResearch(s,active),'Research installment paid. Progress resolves after the full round.');
 graph(host);
 const sharing=document.createElement('section');sharing.className='development-block';sharing.innerHTML=`<h3>Share knowledge or work together</h3><p>Sharing a known discovery is free after the recipient accepts and has its prerequisites. For joint research, both countries select the same project and agree before either funds it. If both pay this round, each gets an extra progress point and 25% of that payment back. Renew cooperation each round.</p><label>Country <select id="rdPartner">${options(state.countries.filter(k=>k.id!==active).map(k=>[k.id,k.name]),'')}</select></label><label>Discovery to share <select id="shareTechnology"></select></label><button id="offerKnowledge" ${locked?'disabled':''}>Offer discovery</button><button id="offerCooperation" ${locked?'disabled':''}>Offer joint research</button><p>${state.partnerships.filter(p=>p.a===active||p.b===active).map(p=>'Partner this round: '+esc(country(p.a===active?p.b:p.a))+' · '+D.techs[p.tech].name).join('')||'No accepted research partner this round.'}</p>`;host.append(sharing);const shareOptions=()=>{const other=state.countries[Number($('rdPartner').value)];$('shareTechnology').innerHTML=options(c.knowledge.filter(k=>other&&D.canLearn(other,k)).map(k=>[k,D.techs[k].name]),'');};$('rdPartner').onchange=shareOptions;shareOptions();$('offerKnowledge').onclick=()=>change(s=>D.offer(s,active,Number($('rdPartner').value),'knowledge',{tech:$('shareTechnology').value}),'Discovery offered; the recipient must accept.');$('offerCooperation').onclick=()=>change(s=>D.offer(s,active,Number($('rdPartner').value),'cooperate',{}),'Joint research offered. Your partner must accept before either country funds research.');relationControls(sharing,'rdPartner',['offerKnowledge','offerCooperation']);exchangeList(sharing,'research');if(locked)sharing.querySelectorAll('button').forEach(b=>b.disabled=true);
 const cities=document.createElement('section');cities.className='development-block';cities.innerHTML='<h3>Your city interiors</h3><p>Settlement level gives 1–5 facility slots. R&D installs facilities using its delivered budget. One construction and one active ability per settlement each round. Click a city to manage it on the map.</p>';for(const t of state.territories.filter(t=>t.owner===active&&t.settlementLevel)){const b=document.createElement('button');b.className='city-card';b.innerHTML=`<span>${esc(t.name)} · ${R.settlementLevels[t.settlementLevel]} · ${t.facilities.length}/${t.settlementLevel} facilities · ${t.actionTurn===state.turn?'action used':'action available'}</span><span class="city-facilities">${DevelopmentArt.built(t).map(k=>`<span title="${D.facilities[k].name}">${DevelopmentArt.facilityIcon(k)}<span>${D.facilities[k].name}</span></span>`).join('')}</span>`;b.onclick=()=>{selected=t.id;popupOpen=true;render();$('territoryPopup').scrollIntoView({block:'center'});};cities.append(b);}host.append(cities);
 for(const [index,token] of c.capturedKnowledge.entries()){const box=document.createElement('article');box.className='event';const eligible=token.options.filter(k=>D.canLearn(c,k));box.innerHTML=`<h3>Captured city archives · ${esc(state.territories[token.territory].name)}</h3><p>Choose one discovery. The former owner keeps its knowledge. This city can provide archives only once to your country.</p><select>${options(eligible.map(k=>[k,D.techs[k].name]),'')}</select><button ${locked||!eligible.length?'disabled':''}>Study captured discovery</button>`;box.querySelector('button').onclick=()=>change(s=>D.claimKnowledge(s,active,index,box.querySelector('select').value),'Captured discovery learned.');host.append(box);}
}
function cityPopup(box,t){const D=R.development,c=state.countries[active],owned=t.owner===active,locked=state.phase!=='orders';box.innerHTML=`<button id="closeTerritory" class="popup-close" aria-label="Close territory upgrades">✕</button><div class="settlement-heading">${SettlementUI.emblem(t)}<h3>${esc(t.name)} · R&D</h3></div>`;if(!owned)box.innerHTML+='<p>Foreign city interiors are not available in this role view.</p>';else if(!t.settlementLevel)box.innerHTML+='<p>Economy must build a village here before you can install facilities.</p>';else{box.innerHTML+=`<p>${R.settlementLevels[t.settlementLevel]} · ${t.facilities.length}/${t.settlementLevel} building slots · ${t.actionTurn===state.turn?'active ability used':'one active ability available'}</p><p>Research budget: ${stockText(c.accounts.research)}</p><h4>Install a facility</h4><select id="facilityKind">${options(Object.entries(D.facilities).filter(([k])=>!t.facilities.includes(k)).map(([k,f])=>[k,f.name+(D.has(c,f.tech)?'':' — needs '+D.techs[f.tech].name)]),'')}</select><div id="facilityPreview" class="facility-preview"></div><p id="facilityCost"></p><button id="installFacility" ${locked||t.builtTurn===state.turn||t.facilities.length>=t.settlementLevel?'disabled':''}>Install using Research funds</button><h4>Active abilities</h4>`;for(const kind of t.facilities){const f=D.facilities[kind],card=document.createElement('article');card.className='facility';card.innerHTML=`<div class="facility-heading">${DevelopmentArt.facilityIcon(kind)}<strong>${f.name}</strong></div><p>${f.action}</p><p>Cost: ${amounts(f.actionCost)}</p>${kind==='hospital'?`<label>Regiment <select>${options(living().filter(u=>u.country===active&&u.territory===t.id&&u.hp<100).map(u=>[u.id,R.types[u.type].name+' #'+u.id+' · '+u.hp+' health']),'')}</select></label>`:''}<button ${locked||t.actionTurn===state.turn?'disabled':''}>Use ${f.name}</button>`;card.querySelector('button').onclick=()=>{const id=kind==='hospital'?Number(card.querySelector('select').value):null;change(s=>D.cityAction(s,active,t.id,kind,id),'City ability chosen. Treatment, manufacturing and research boosts resolve at round-end.');};box.append(card);}const preview=()=>{const kind=$('facilityKind').value,f=D.facilities[kind];$('facilityPreview').innerHTML=f?DevelopmentArt.facilityIcon(kind):'';const canAfford=f&&R.goods.every(g=>c.accounts.research[g]>=(f.cost[g]||0));$('installFacility').disabled=locked||t.builtTurn===state.turn||t.facilities.length>=t.settlementLevel||!f||!D.has(c,f.tech)||!canAfford;$('installFacility').textContent=f&&!D.has(c,f.tech)?'Research required':f&&!canAfford?'Needs more Research resources':'Install using Research funds';$('facilityCost').textContent=f?'Cost: '+amounts(f.cost)+'. Requires '+D.techs[f.tech].name+'.':'All facility types are installed.';};$('facilityKind').onchange=preview;preview();$('installFacility').onclick=()=>change(s=>D.install(s,active,t.id,$('facilityKind').value),'Facility installed.');}box.append(Object.assign(document.createElement('p'),{id:'popupNotice',textContent:$('notice').textContent}));$('closeTerritory').onclick=()=>{popupOpen=false;box.hidden=true;$('territory').focus({preventScroll:true});};}
return {trades,research,cityPopup,researchCategories};})();
